  ('ab6797f7e3b007fcaf6a87c571fb3e5d', 'Würdest du gern mal ein Toy oder Hilfsmittel ausprobieren, das du dich bisher nicht laut auszusprechen getraut hast?'),
  ('cb3a918cfd0d853f7fc778cddd644150', 'Wie sehr erregt dich der Gedanke, dabei beobachtet zu werden? (1 = gar nicht, 5 = sehr)'),
  ('a6d64cfd369b81d4399dead9779233f0', 'Was ist die eine Sache, die du im Bett viel öfter von mir hören oder erleben möchtest?'),
  ('7f9630321621324301e1861e4f8031fa', 'Erregt dich die Vorstellung, dass wir es an einem riskanten Ort miteinander ausprobieren, an dem uns beinahe jemand erwischt?'),
  ('e1bc33de1649aa31f276f0496b230a19', 'Fantasierst du manchmal davon, die völlige Kontrolle über das Geschehen zu übernehmen?'),
  ('76e3a89890781fdc8c9dc3d38b8973ad', 'Welche deiner Fantasien kommt dir so wild vor, dass du dich bisher nicht getraut hast, sie laut auszusprechen?'),
  ('181fcb40105fa81ba5928cb53bc5444c', 'Wenn du dir eine erotische Fantasie ohne jegliche Konsequenzen erfüllen könntest, welche wäre das?'),
  ('5870d8b8324c1dbb958be0c0104c9bbe', 'Wie oft träumst du von etwas, das wir noch nie zusammen ausprobiert haben? (1 = fast nie, 5 = fast ständig)'),
  ('bf84a0746dfd9027c27242720d50c085', 'Würde es dich reizen, jemand völlig anderen zu spielen – in eine Rolle zu schlüpfen, die dir sonst fremd ist?'),
  ('d3435078d944167172e53c9b1cfc6dbd', 'Reizt dich die Vorstellung, mich (oder dich) fesseln zu lassen?')
) as v(cs_md5, prompt)
join questions q on md5(q.prompt) = v.cs_md5
on conflict (question_id, locale) do update set prompt = excluded.prompt;

-- ===== fr =====
insert into question_translations (question_id, locale, prompt)
select q.id, 'fr', v.prompt
from (values
  ('01c948b32d77a5758a64fd0332e0c7a2', 'À quelle fréquence, dans les moments difficiles, regrettes-tu qu’on se soit mis ensemble ? (1 = jamais, 5 = à chaque grosse dispute)'),
  ('ef5a4c2f236a16f0b3e0cf775952a8d4', 'Quel geste, quel mot ou quel contact en dehors de la chambre (dans la journée) te met à coup sûr d’humeur pour faire l’amour le soir ?'),
